Given a head of the  linked list, we need to remove the first node from the given linked list.Examples:Input : Output : 2 -> 3 -> 1 -> 7 -> NULLExplanation: After deleting head from the given linked list, we'll be left with just 2 -> 3 -> 1 -> 7. Input :  Output : 5 -> 7 -> 8 -> 99 -> 100 -> NULL Explanation: After deleting head from the given linked list, we'll be left with just 5 -> 7 -> 8 -> 99 -> 100. Try It YourselfBy Shifting head node to next node of head - O(1) Time and O(1) SpaceTo remove the first node of a linked list, store the current head in a temporary variable (temp), move the head pointer to the next node, delete the temporary head node and finally , return the new head of the linked list.Below is the implementation of the above approach:
            C++

    #include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node *next;
    Node(int x) {
        data = x;
        next = nullptr;
    }
};

// Delete the head node and return the new head
Node* deleteHead(Node* head) {

    // Check if the list is empty
    if (head == nullptr)
        return nullptr;

    // Store the current head in a
    // temporary variable
    Node* temp = head;

    // Move the head pointer to the next node
    head = head->next;

    // Free the memory of the old head node
    delete temp;

    return head;
}

// Function to print the linked list
void printList(Node* curr) {
    while (curr != nullptr) {
        cout << curr->data;
        if (curr->next != nullptr) {
            cout << " -> ";
        }
        curr = curr->next; 
    }
}

int main() {

    // Create a hard-coded linked list:
    // 8 -> 2 -> 3 -> 1 -> 7
    Node* head = new Node(8);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(1);
    head->next->next->next->next = new Node(7);

    head = deleteHead(head); 
    printList(head);

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

// Define a linked list node
struct Node
{
    int data;
    struct Node *next;
};

// Function to create a new node
struct Node *createNode(int x)
{
    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
    newNode->data = x;
    newNode->next = NULL;
    return newNode;
}

// Delete the head node and return the new head
struct Node *deleteHead(struct Node *head)
{
    if (head == NULL)
        return NULL;

    struct Node *temp = head;
    head = head->next;
    free(temp); // Free memory of old head

    return head;
}

// Function to print the linked list
void printList(struct Node *curr)
{
    while (curr != NULL)
    {
        printf("%d", curr->data);
        if (curr->next != NULL)
            printf(" -> ");
        curr = curr->next;
    }
    printf("\n");
}

int main()
{
    // Create a hard-coded linked list: 8 -> 2 -> 3 -> 1 -> 7
    struct Node *head = createNode(8);
    head->next = createNode(2);
    head->next->next = createNode(3);
    head->next->next->next = createNode(1);
    head->next->next->next->next = createNode(7);

    // Delete the head node
    head = deleteHead(head);

    // Print the updated list
    printList(head);

    return 0;
}


