    using System;

class Node {
    public int data;
    public Node next;

    public Node(int x) {
        data = x;
        next = null;
    }
}

class GfG {

    // Delete the head node and return the new head
    public static Node DeleteHead(Node head) {

        // Check if the list is empty
        if (head == null)
            return null;

        // Move the head pointer to the next node
        Node temp = head;
        head = head.next;

        // Free the memory of the old head node
        temp = null;

        return head;
    }

